// In-game facility map.
// - Compact: a small north-up minimap that follows the player and names the
//   current room.
// - Expanded: the whole plan with room cards, a room index, workflow routes and
//   a legend, like the published floor-plan viewer.
// Both draw the plan generated by scripts/facility/floorplan.mjs, so the game
// and the published plan never drift apart. Closed by default; M toggles it.
// It renders through a portal so station panels never cover it, and samples
// the camera only while it is open.
import { useCallback, useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore, type CSSProperties, type RefObject } from 'react'
import { createPortal } from 'react-dom'
import { MAP_DATA, MAP_STYLE, MAP_SVG, MAP_VIEW, type MapRoom } from '../three/lab/facilityMap.gen'
import type { LabWorld } from '../three/lab/world'

// ── session state: survives station switches, closed until asked for ───────
interface MapState {
  open: boolean
  expanded: boolean
  /** compact zoom step (index into SPANS) */
  zoom: number
}
let mapState: MapState = { open: false, expanded: false, zoom: 1 }
const subscribers = new Set<() => void>()
export const mapStore = {
  get: () => mapState,
  subscribe(cb: () => void) {
    subscribers.add(cb)
    return () => {
      subscribers.delete(cb)
    }
  },
  set(patch: Partial<MapState>) {
    mapState = { ...mapState, ...patch }
    subscribers.forEach((cb) => cb())
  },
  toggle() {
    mapStore.set(mapState.open || mapState.expanded ? { open: false, expanded: false } : { open: true })
  },
}
export const useMapState = () => useSyncExternalStore(mapStore.subscribe, mapStore.get)

// ── plan geometry ───────────────────────────────────────────────────────────
const V = MAP_VIEW
/** scene units → plan units */
const toPlan = (x: number, z: number): [number, number] => [
  (x * V.metresPerUnit - V.minX + V.margin) * V.scale,
  (z * V.metresPerUnit - V.minZ + V.margin + V.head) * V.scale,
]
const ROOMS = new Map(MAP_DATA.rooms.map((r) => [r.id, r]))
const ROOM_OF_ZONE = new Map(MAP_DATA.rooms.map((r) => [r.zone, r]))
const GROUP_ORDER = ['hub', 'life', 'core', 'chem', 'support', 'circulation']
/** metres across the compact map, by zoom step */
const SPANS = [8, 13, 20]
const COMPACT_W = 252
const COMPACT_H = 188
const ENTRY: Record<string, string> = {
  hub: 'The hub',
  circulation: 'A corridor or lobby',
  'via-parent': 'Through its parent room',
  'via-foyer': 'Through its own anteroom',
  service: 'Service access only',
}
const packName = (id: string) => (id === 'base' ? 'Every add-on' : (MAP_DATA.packs.find((p) => p.id === id)?.name ?? id))
const headingDeg = (h: number) => (Math.atan2(Math.cos(h), Math.sin(h)) * 180) / Math.PI

let styleInjected = false
function injectStyle() {
  if (styleInjected) return
  const el = document.createElement('style')
  el.textContent = MAP_STYLE
  document.head.appendChild(el)
  styleInjected = true
}

interface Pose {
  x: number
  z: number
  heading: number
  zone: string | null
}

/** Sample the camera every frame while mounted; `apply` runs only when it changed. */
function usePose(getWorld: () => LabWorld | null, apply: (p: Pose) => void, resetKey: unknown) {
  const applyRef = useRef(apply)
  applyRef.current = apply
  useEffect(() => {
    let raf = 0
    let last = ''
    const loop = () => {
      raf = requestAnimationFrame(loop)
      const w = getWorld()
      if (!w) return
      const p = w.player
      const key = `${p.x.toFixed(3)}|${p.z.toFixed(3)}|${w.heading.toFixed(3)}|${w.currentZone}`
      if (key === last) return
      last = key
      applyRef.current({ x: p.x, z: p.z, heading: w.heading, zone: w.currentZone })
    }
    raf = requestAnimationFrame(loop)
    return () => cancelAnimationFrame(raf)
  }, [getWorld, resetKey])
}

/** Mark rooms on the plan (current room, selection, route) without re-rendering it. */
function markRooms(svg: SVGSVGElement | null, cls: string, ids: string[]) {
  if (!svg) return
  svg.querySelectorAll(`.fp-floors .${cls}`).forEach((el) => el.classList.remove(cls))
  for (const id of ids) svg.querySelector(`.fp-floors [data-room="${id}"]`)?.classList.add(cls)
}

/** The plan, plus a "you are here" marker drawn pointing along +x. */
function Plan({ svgRef, meRef, className, style, viewBox, onClick, children }: {
  svgRef: RefObject<SVGSVGElement | null>
  meRef: RefObject<SVGGElement | null>
  className?: string
  style?: CSSProperties
  viewBox: string
  onClick?: (e: React.MouseEvent<SVGSVGElement>) => void
  children?: React.ReactNode
}) {
  return (
    <svg ref={svgRef} className={`fp ${className ?? ''}`} viewBox={viewBox} style={style} onClick={onClick} role="img" aria-label="Facility floor plan">
      <g dangerouslySetInnerHTML={{ __html: MAP_SVG }} />
      <g ref={meRef} className="lab-map-me">
        <path className="lab-map-cone" d="M0,0 L36,-17 A40,40 0 0 1 36,17 Z" />
        <circle className="lab-map-dot" r="7" />
        <path className="lab-map-arrow" d="M9,0 L-4,-6 L-1.5,0 L-4,6 Z" />
      </g>
      {children}
    </svg>
  )
}

/** The scene's box on screen, so the map can float over station panels. */
export function useSceneRect(ref: RefObject<HTMLElement | null>) {
  const [rect, setRect] = useState<DOMRect | null>(null)
  // a passive effect: the parent's ref is attached only after child layout effects
  useEffect(() => {
    const el = ref.current
    if (!el) return
    const update = () => setRect(el.getBoundingClientRect())
    update()
    const ro = new ResizeObserver(update)
    ro.observe(el)
    window.addEventListener('resize', update)
    window.addEventListener('scroll', update, true)
    return () => {
      ro.disconnect()
      window.removeEventListener('resize', update)
      window.removeEventListener('scroll', update, true)
    }
  }, [ref])
  return rect
}

export interface MapAnchor {
  right: number
  bottom: number
}

export function LabMap({ getWorld, containerRef, anchor = { right: 12, bottom: 56 }, floatingButton = false }: {
  getWorld: () => LabWorld | null
  /** the scene's box: the map docks inside it */
  containerRef: RefObject<HTMLElement | null>
  anchor?: MapAnchor
  /** show a small "Map" button when closed (for hosts without the camera bar) */
  floatingButton?: boolean
}) {
  const s = useMapState()
  const rect = useSceneRect(containerRef)
  useEffect(injectStyle, [])

  // M toggles the map; Esc steps back from the full map
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return
      const t = e.target as HTMLElement | null
      if (t?.closest?.('input, textarea, select, [contenteditable="true"]')) return
      if (e.key === 'm' || e.key === 'M') mapStore.toggle()
      else if (e.key === 'Escape' && mapStore.get().expanded) mapStore.set({ expanded: false, open: true })
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  if (!rect) return null
  const dock: CSSProperties = {
    position: 'fixed',
    right: Math.max(0, window.innerWidth - rect.right) + anchor.right,
    bottom: Math.max(0, window.innerHeight - rect.bottom) + anchor.bottom,
  }
  let body: React.ReactNode = null
  if (s.expanded) {
    const inset = 10
    body = (
      <Expanded
        getWorld={getWorld}
        style={{ position: 'fixed', left: rect.left + inset, top: rect.top + inset, width: Math.max(320, rect.width - inset * 2), height: Math.max(280, rect.height - inset * 2) }}
      />
    )
  } else if (s.open) body = <Compact getWorld={getWorld} zoom={s.zoom} style={dock} />
  else if (floatingButton)
    body = (
      <button type="button" data-testid="map-toggle" className="lab-map-pill" style={dock} onClick={() => mapStore.set({ open: true })} title="Show the map (M)">
        <MapIcon /> Map
      </button>
    )
  return body ? createPortal(<div className="lab-map">{body}</div>, document.body) : null
}

export function MapIcon() {
  return (
    <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true">
      <path strokeLinecap="round" strokeLinejoin="round" d="M9 6.75V15m6-6v8.25m.503 3.498l4.875-2.437c.381-.19.622-.58.622-1.006V4.82c0-.836-.88-1.38-1.628-1.006l-3.869 1.934c-.317.159-.69.159-1.006 0L9.503 3.252a1.125 1.125 0 00-1.006 0L3.622 5.689C3.24 5.88 3 6.27 3 6.695V19.18c0 .836.88 1.38 1.628 1.006l3.869-1.934c.317-.159.69-.159 1.006 0l4.994 2.497c.317.158.69.158 1.006 0z" />
    </svg>
  )
}

// ── compact minimap ─────────────────────────────────────────────────────────
function Compact({ getWorld, zoom, style }: { getWorld: () => LabWorld | null; zoom: number; style: CSSProperties }) {
  const svgRef = useRef<SVGSVGElement>(null)
  const meRef = useRef<SVGGElement>(null)
  const [room, setRoom] = useState<MapRoom | null>(null)
  const hereRef = useRef<string | null>(null)
  usePose(
    getWorld,
    (p) => {
      const [px, py] = toPlan(p.x, p.z)
      const vw = SPANS[zoom] * V.scale
      const vh = vw * (COMPACT_H / COMPACT_W)
      svgRef.current?.setAttribute('viewBox', `${px - vw / 2} ${py - vh / 2} ${vw} ${vh}`)
      meRef.current?.setAttribute('transform', `translate(${px} ${py}) rotate(${headingDeg(p.heading)}) scale(${vw / COMPACT_W})`)
      const r = p.zone ? (ROOM_OF_ZONE.get(p.zone) ?? null) : null
      if ((r?.id ?? null) !== hereRef.current) {
        hereRef.current = r?.id ?? null
        markRooms(svgRef.current, 'is-here', r ? [r.id] : [])
        setRoom(r)
      }
    },
    zoom,
  )
  // a fresh plan element needs the current room marked again
  useEffect(() => markRooms(svgRef.current, 'is-here', hereRef.current ? [hereRef.current] : []))
  return (
    <section className={`ui-panel lab-map-compact lab-map-zoom-${zoom} overflow-hidden`} style={{ ...style, width: COMPACT_W + 2 }} aria-label="Minimap">
      <header className="flex items-center gap-2 px-2.5 py-1.5 border-b border-[var(--line)]">
        <span className="font-mono-ui text-[10.5px] font-bold text-[var(--accent)]">{room?.id ?? '—'}</span>
        <span className="flex-1 min-w-0 truncate text-[11.5px] text-[var(--ink)]" title={room?.name}>
          {room?.name ?? 'Outside'}
        </span>
        <MapButton testId="map-zoom-out" label="Zoom out" disabled={zoom >= SPANS.length - 1} onClick={() => mapStore.set({ zoom: Math.min(SPANS.length - 1, zoom + 1) })}>
          −
        </MapButton>
        <MapButton testId="map-zoom-in" label="Zoom in" disabled={zoom <= 0} onClick={() => mapStore.set({ zoom: Math.max(0, zoom - 1) })}>
          +
        </MapButton>
        <MapButton testId="map-expand" label="Open the full map" onClick={() => mapStore.set({ expanded: true })}>
          ⤢
        </MapButton>
        <MapButton testId="map-close" label="Close the map (M)" onClick={() => mapStore.set({ open: false })}>
          ×
        </MapButton>
      </header>
      <Plan svgRef={svgRef} meRef={meRef} viewBox={`0 0 ${V.width} ${V.height}`} style={{ width: COMPACT_W, height: COMPACT_H }} />
    </section>
  )
}

function MapButton({ testId, label, onClick, disabled, children }: { testId: string; label: string; onClick: () => void; disabled?: boolean; children: React.ReactNode }) {
  return (
    <button
      type="button"
      data-testid={testId}
      aria-label={label}
      title={label}
      disabled={disabled}
      onClick={onClick}
      className="w-6 h-6 rounded-md text-[13px] leading-none text-[var(--muted)] hover:text-[var(--ink)] hover:bg-[var(--bg-2)] disabled:opacity-35 disabled:hover:bg-transparent"
    >
      {children}
    </button>
  )
}

// ── full map ────────────────────────────────────────────────────────────────
function Expanded({ getWorld, style }: { getWorld: () => LabWorld | null; style: CSSProperties }) {
  const svgRef = useRef<SVGSVGElement>(null)
  const meRef = useRef<SVGGElement>(null)
  const scrollRef = useRef<HTMLDivElement>(null)
  const poseRef = useRef<Pose | null>(null)
  const startZone = getWorld()?.currentZone
  const [selected, setSelected] = useState(() => (startZone && ROOM_OF_ZONE.get(startZone)?.id) || 'C01')
  const [workflow, setWorkflow] = useState('')
  const [zoom, setZoom] = useState(0.5)
  const [here, setHere] = useState<string | null>(null)

  const centreOn = useCallback(
    (px: number, py: number, smooth: boolean) => {
      const c = scrollRef.current
      if (!c) return
      c.scrollTo({ left: px * zoom - c.clientWidth / 2, top: py * zoom - c.clientHeight / 2, behavior: smooth ? 'smooth' : 'auto' })
    },
    [zoom],
  )
  const centreOnMe = (smooth: boolean) => {
    const p = poseRef.current
    if (p) centreOn(...toPlan(p.x, p.z), smooth)
  }

  // fit the plan to the panel's width, then start centred on the player
  useLayoutEffect(() => {
    const c = scrollRef.current
    if (c) setZoom(Math.max(0.3, Math.min(1, (c.clientWidth - 2) / V.width)))
  }, [])
  const centred = useRef(false)

  usePose(
    getWorld,
    (p) => {
      poseRef.current = p
      const [px, py] = toPlan(p.x, p.z)
      meRef.current?.setAttribute('transform', `translate(${px} ${py}) rotate(${headingDeg(p.heading)}) scale(${1 / zoom})`)
      const id = p.zone ? (ROOM_OF_ZONE.get(p.zone)?.id ?? null) : null
      setHere(id)
      if (!centred.current) {
        centred.current = true
        centreOn(px, py, false)
      }
    },
    zoom,
  )

  const wf = MAP_DATA.workflows.find((w) => w.id === workflow)
  useEffect(() => {
    markRooms(svgRef.current, 'is-here', here ? [here] : [])
    markRooms(svgRef.current, 'is-selected', [selected])
    markRooms(svgRef.current, 'is-route', wf?.route ?? [])
  })

  const select = (id: string, scroll: boolean) => {
    const r = ROOMS.get(id)
    if (!r) return
    setSelected(id)
    if (scroll) centreOn(r.lx, r.ly, true)
  }
  const onPlanClick = (e: React.MouseEvent<SVGSVGElement>) => {
    const g = (e.target as Element).closest('.fp-floors [data-room]')
    const id = g?.getAttribute('data-room')
    if (id) select(id, false)
  }
  const setZoomKeep = (z: number) => {
    const c = scrollRef.current
    const nz = Math.max(0.3, Math.min(2.5, z))
    if (c) {
      const cx = (c.scrollLeft + c.clientWidth / 2) / zoom
      const cy = (c.scrollTop + c.clientHeight / 2) / zoom
      setZoom(nz)
      requestAnimationFrame(() => c.scrollTo({ left: cx * nz - c.clientWidth / 2, top: cy * nz - c.clientHeight / 2 }))
    } else setZoom(nz)
  }

  const playable = MAP_DATA.rooms.filter((r) => !r.nonPlayable)
  const area = Math.round(playable.reduce((s, r) => s + r.area, 0))
  const far = playable.reduce((m, r) => ((r.fromHub ?? 0) > (m.fromHub ?? 0) ? r : m), playable[0])
  const room = ROOMS.get(selected)

  return (
    <section className="ui-panel lab-map-full flex flex-col overflow-hidden" style={style} role="dialog" aria-label="Facility map">
      <header className="flex flex-wrap items-center gap-x-5 gap-y-2 px-4 py-2.5 border-b border-[var(--line)]">
        <div className="min-w-0">
          <h2 className="text-[15px] font-semibold text-[var(--ink)] leading-tight">Facility map</h2>
          <p className="text-[11px] text-[var(--muted)]">
            {here ? (
              <>
                You are in <b className="text-[var(--ink)]">{ROOMS.get(here)?.name}</b>
              </>
            ) : (
              'You are outside the rooms'
            )}
          </p>
        </div>
        <dl className="flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-[var(--muted)]">
          <Stat value={String(playable.length)} label="rooms" />
          <Stat value={`${area} m²`} label="floor area" />
          <Stat value={`${Math.round(far?.fromHub ?? 0)} m`} label={`farthest walk (${far?.id})`} />
          <Stat value={`${Math.round(MAP_DATA.occupancy * 100)}%`} label="of hub sectors used" />
        </dl>
        <label className="flex items-center gap-2 text-[11px] text-[var(--muted)]">
          Workflow
          <select
            value={workflow}
            onChange={(e) => setWorkflow(e.target.value)}
            className="rounded-md border border-[var(--line)] bg-[var(--surface-solid)] px-1.5 py-1 text-[11.5px] text-[var(--ink)]"
          >
            <option value="">None</option>
            {MAP_DATA.workflows.map((w) => (
              <option key={w.id} value={w.id}>
                {w.name}
              </option>
            ))}
          </select>
        </label>
        <div className="ml-auto flex items-center gap-1">
          <button type="button" className="lab-map-btn" onClick={() => centreOnMe(true)}>
            Centre on me
          </button>
          <button type="button" className="lab-map-btn" aria-label="Zoom out" onClick={() => setZoomKeep(zoom / 1.25)}>
            −
          </button>
          <button
            type="button"
            className="lab-map-btn"
            onClick={() => {
              const c = scrollRef.current
              if (c) setZoom(Math.max(0.3, Math.min(1, (c.clientWidth - 2) / V.width)))
            }}
          >
            Fit
          </button>
          <button type="button" className="lab-map-btn" aria-label="Zoom in" onClick={() => setZoomKeep(zoom * 1.25)}>
            +
          </button>
          <button type="button" data-testid="map-minimap" className="lab-map-btn" onClick={() => mapStore.set({ expanded: false, open: true })} title="Back to the minimap (Esc)">
            Minimap
          </button>
          <button type="button" data-testid="map-close" className="lab-map-btn" aria-label="Close the map (M)" title="Close the map (M)" onClick={() => mapStore.set({ expanded: false, open: false })}>
            ×
          </button>
        </div>
      </header>
      {wf && (
        <div className="px-4 py-1.5 border-b border-[var(--line)] font-mono-ui text-[11px] text-[var(--muted)]">
          {wf.route.join(' → ')} · {Math.round(wf.metres)} m door to door
        </div>
      )}
      <div className="flex-1 min-h-0 flex flex-col md:flex-row">
        <div className="flex-1 min-w-0 min-h-0 flex flex-col">
          <div ref={scrollRef} className="flex-1 min-h-0 overflow-auto bg-[var(--surface-solid)]">
            <Plan
              svgRef={svgRef}
              meRef={meRef}
              className="lab-map-plan"
              viewBox={`0 0 ${V.width} ${V.height}`}
              style={{ width: V.width * zoom, height: V.height * zoom }}
              onClick={onPlanClick}
            >
              {wf?.route.map((id, i) => {
                const r = ROOMS.get(id)
                if (!r) return null
                return (
                  <g key={id + i} className="lab-map-badge">
                    <circle cx={r.lx - 26} cy={r.ly - 18} r={9} />
                    <text x={r.lx - 26} y={r.ly - 14} textAnchor="middle">
                      {i + 1}
                    </text>
                  </g>
                )
              })}
            </Plan>
          </div>
          <Legend />
        </div>
        <aside className="md:w-[330px] shrink-0 min-h-0 overflow-auto border-t md:border-t-0 md:border-l border-[var(--line)] p-4 space-y-4">
          {room && <RoomCard room={room} here={room.id === here} />}
          <RoomIndex selected={selected} onPick={(id) => select(id, true)} />
        </aside>
      </div>
    </section>
  )
}

function Stat({ value, label }: { value: string; label: string }) {
  return (
    <div className="flex items-baseline gap-1.5">
      <dt className="sr-only">{label}</dt>
      <dd className="font-mono-ui font-semibold text-[var(--ink)]">{value}</dd>
      <span aria-hidden="true">{label}</span>
    </div>
  )
}

function Legend() {
  return (
    <div className="lab-map-legend flex flex-wrap gap-x-4 gap-y-1 px-4 py-2 border-t border-[var(--line)] text-[11px] text-[var(--muted)]">
      {GROUP_ORDER.map((g) => (
        <span key={g}>
          <i className={`fp-room fp-g-${g}`} />
          {MAP_DATA.groups[g]?.name}
        </span>
      ))}
      <span>
        <i className="lab-map-legend-built" />
        Built from the reference photos
      </span>
      <span>
        <b className="text-[var(--warn)]">→</b> One-way door
      </span>
      <span>Dashed rooms: service space</span>
      <span>Hatched wedges: reserved sectors</span>
    </div>
  )
}

function RoomCard({ room, here }: { room: MapRoom; here: boolean }) {
  const phase = MAP_DATA.phases.find((p) => p.id === room.phase)
  const parent = room.parent ? ROOMS.get(room.parent) : null
  const tags: [string, string][] = [[MAP_DATA.groups[room.group]?.name ?? room.group, '']]
  if (here) tags.push(['You are here', 'accent'])
  if (room.existing) tags.push(['Built from the photos', 'ok'])
  if (room.shared && room.group !== 'core') tags.push(['Shared core', ''])
  if (room.controlled) tags.push(['Controlled access', 'warn'])
  if (room.nonPlayable) tags.push(['Service space, not walkable', ''])
  return (
    <article className="lab-map-card text-[12.5px] text-[var(--ink)]" aria-live="polite">
      <div className="font-mono-ui text-[11.5px] font-bold text-[var(--accent)]">{room.id}</div>
      <h3 className="text-[16px] font-semibold leading-snug">{room.name}</h3>
      <div className="flex flex-wrap gap-1.5 my-2">
        {tags.map(([t, tone]) => (
          <span key={t} className={`lab-map-tag ${tone}`}>
            {t}
          </span>
        ))}
      </div>
      {room.purpose && <p className="text-[var(--muted)] leading-relaxed">{room.purpose}</p>}
      <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1 my-3">
        <dt className="text-[var(--muted)]">Entered</dt>
        <dd>{ENTRY[room.entry ?? ''] ?? '–'}</dd>
        {parent && (
          <>
            <dt className="text-[var(--muted)]">Part of</dt>
            <dd>
              {parent.id} {parent.name}
            </dd>
          </>
        )}
        <dt className="text-[var(--muted)]">Doors to</dt>
        <dd>{room.doors.map((d) => `${d} ${ROOMS.get(d)?.short ?? ''}`.trim()).join(', ') || '–'}</dd>
        <dt className="text-[var(--muted)]">Add-ons</dt>
        <dd>{room.packs.map(packName).join(', ')}</dd>
        <dt className="text-[var(--muted)]">Build phase</dt>
        <dd>{phase ? `${phase.id} · ${phase.name}` : '–'}</dd>
        <dt className="text-[var(--muted)]">Floor area</dt>
        <dd>{Math.round(room.area)} m²</dd>
        <dt className="text-[var(--muted)]">Walk from hub</dt>
        <dd>{room.fromHub == null ? '–' : `${Math.round(room.fromHub)} m`}</dd>
      </dl>
      <CardList title="Fixed equipment" items={room.fixed} />
      <CardText title="Kept in storage" text={room.stored} />
      <CardText title="Sample policy" text={room.samplePolicy} />
      <CardList title="Hazards" items={room.hazards} />
      <CardList title="Services" items={room.utilities} />
      <CardText title="Notes" text={room.notes} />
    </article>
  )
}

function CardList({ title, items }: { title: string; items: string[] }) {
  if (!items.length) return null
  return (
    <section className="mt-3">
      <h4 className="lab-map-h">{title}</h4>
      <ul className="list-disc pl-4 space-y-0.5">
        {items.map((x) => (
          <li key={x}>{x}</li>
        ))}
      </ul>
    </section>
  )
}

function CardText({ title, text }: { title: string; text: string }) {
  if (!text) return null
  return (
    <section className="mt-3">
      <h4 className="lab-map-h">{title}</h4>
      <p className="leading-relaxed">{text}</p>
    </section>
  )
}

function RoomIndex({ selected, onPick }: { selected: string; onPick: (id: string) => void }) {
  return (
    <nav aria-label="Room index" className="text-[12px]">
      {GROUP_ORDER.map((g) => {
        const rooms = MAP_DATA.rooms.filter((r) => r.group === g).sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }))
        if (!rooms.length) return null
        return (
          <div key={g} className="mb-3">
            <h4 className="lab-map-h">{MAP_DATA.groups[g]?.name}</h4>
            <ul className="space-y-px">
              {rooms.map((r) => (
                <li key={r.id}>
                  <button
                    type="button"
                    data-testid={`map-room-${r.id}`}
                    onClick={() => onPick(r.id)}
                    aria-current={r.id === selected}
                    className={`w-full text-left flex gap-2 px-1.5 py-0.5 rounded hover:bg-[var(--accent-soft)] ${r.id === selected ? 'bg-[var(--accent-soft)]' : ''}`}
                  >
                    <code className="font-mono-ui text-[11px] text-[var(--muted)] min-w-[3.4em]">{r.id}</code>
                    <span className="min-w-0 truncate">{r.name}</span>
                  </button>
                </li>
              ))}
            </ul>
          </div>
        )
      })}
    </nav>
  )
}
